const inbound = $input.first().json;
const envelope = inbound.body && typeof inbound.body === 'object' ? inbound.body : inbound;
const payload = envelope.payload && typeof envelope.payload === 'object' ? envelope.payload
  : (envelope.message && typeof envelope.message === 'object' ? envelope.message : envelope);
const inner = payload.message && typeof payload.message === 'object' ? payload.message : payload;
const pick = (...vals) => vals.find(v => typeof v === 'string' && v.trim().length > 0) || '';
const text = pick(inner.body, inner.text, inner.message?.conversation,
  inner.message?.extendedTextMessage?.text, payload.body, payload.text, envelope.text);
const chatId = pick(inner.from, inner.chatId, inner.key?.remoteJid, payload.chatId,
  payload.from, envelope.chatId);
const rawId = inner.id ?? inner.key?.id ?? payload.id ?? envelope.id;
const messageId = typeof rawId === 'string' ? rawId :
  typeof rawId === 'object' && rawId ? pick(rawId._serialized, rawId.id) : '';
const fromMe = inner.fromMe === true || inner.key?.fromMe === true || payload.fromMe === true;
const eventType = pick(envelope.event, envelope.type, 'message');
const isGroup = chatId.endsWith('@g.us') || inner.isGroup === true || payload.isGroup === true;
let hash = 2166136261;
for (const c of chatId + ':' + (messageId || text)) {
  hash ^= c.codePointAt(0);
  hash = Math.imul(hash, 16777619);
}
const externalId = 'demo-waha-' + (hash >>> 0).toString(16).padStart(8, '0');
return [{ json: {
  external_id: externalId,
  message_id: messageId || 'text-fingerprint',
  text: String(text).slice(0,5000),
  is_group: isGroup,
  from_me: fromMe,
  event_type: eventType,
  test_retry: payload.test_retry === true || envelope.test_retry === true,
  source: 'waha-webhook'
}}];

const m = $input.first().json;
const text = m.text || '';
const ignoreReason = !m.is_group ? 'not_group_message'
  : m.from_me ? 'own_message'
  : !/(^message(?:\.any)?$)/i.test(m.event_type) ? 'unrelated_event'
  : !text.trim() ? 'empty_text' : '';
if (ignoreReason) return [{json:{state:'ignored',reason:ignoreReason,external_id:m.external_id}}];
const notJob = /(not hiring|no job openings|looking for an apartment|just checking lunch|house for rent|for sale|صباح الخير|إعلان بيع|غير مطلوب موظفين)/i;
const roleTable = [
  ['Camera Operator', /\b(camera operator|camera person|cameraman)\b/i],
  ['Video Editor', /\b(video editor|film editor|editing videos)\b/i],
  ['Production Assistant', /\b(production assistant|production runner)\b/i],
  ['Videographer', /\b(videographer)\b/i],
  ['Sound Engineer', /\b(sound engineer|audio engineer)\b/i],
  ['Event Coordinator', /\b(event coordinator|event assistant)\b/i],
  ['Lighting Technician', /\b(lighting technician|gaffer)\b/i],
  ['Photographer', /\b(photographer)\b/i],
  ['Motion Graphics Designer', /\b(motion graphics designer|motion designer)\b/i],
  ['مصور فيديو', /(مصور فيديو|مصور ڤيديو)/],
  ['مصور', /(مصور|كاميرا مان)/],
  ['مونتير', /(مونتير|محرر فيديو)/],
  ['مساعد إنتاج', /(مساعد إنتاج|مساعد انتاج)/],
  ['مهندس صوت', /(مهندس صوت)/],
  ['منسق فعاليات', /(منسق فعاليات)/]
];
const intent = /(hiring|we (?:are )?looking for|looking for a|need(?:ed)?|seeking|vacancy|job opening|crew call|casting|production assistant|video editor|مطلوب|فرصة عمل|نبحث عن|توظيف|وظيفة|محتاجين)/i.test(text);
if (notJob.test(text) || !intent) {
  return [{json:{state:'ignored',reason:notJob.test(text)?'non_job_message':'no_hiring_intent',external_id:m.external_id}}];
}
const role = roleTable.find(([name,pat]) => pat.test(text));
const cities = [
 ['Dubai',/(Dubai|دبي)/i],['Abu Dhabi',/(Abu Dhabi|Abudhabi|أبو ?ظبي|ابو ?ظبي)/i],
 ['Sharjah',/(Sharjah|الشارقة)/i],['Ajman',/(Ajman|عجمان)/i],
 ['Al Ain',/(Al Ain|العين)/i],['Ras Al Khaimah',/(Ras Al Khaimah|رأس الخيمة)/i]
];
const city = cities.find(([name,pat])=>pat.test(text))?.[0] || '';
const titlePattern = text.match(/(?:^|\n)\s*(?:Role|Position|Job\s*Title)\s*[:\-]\s*([^\n]{4,100})/i);
const title = role?.[0] || (titlePattern ? titlePattern[1].trim() : '');
const normalizedDigits = text.replace(/[٠-٩۰-۹]/g, c =>
  String(c.charCodeAt(0) - (c.charCodeAt(0) >= 0x06F0 ? 0x06F0 : 0x0660)));
const pay = normalizedDigits.match(/(?:AED|DHS?|د\.?\s?إ)\s?[0-9,]+(?:\.[0-9]+)?\s?[kK]?(?:\s?\/\s?(?:day|يوم))?|[0-9,]+(?:\.[0-9]+)?\s?[kK]?(?:\s?\/\s?(?:day|يوم))?\s?(?:AED|DHS?|درهم)|\b[0-9]+(?:\.[0-9]+)?\s?[kK]\s?\/\s?day\b/i)?.[0] || '';
const workDate = text.match(/\b\d{1,2}[\/-]\d{1,2}[\/-]\d{4}\b|\b\d{1,2}\s+(?:Oct|Nov|Dec|Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep)\b/i)?.[0] || '';
const employmentType = /(?:freelance|فريلانسر|مستقل)/i.test(text) ? 'freelance'
 : /(?:part.time|دوام جزئي)/i.test(text) ? 'part-time'
 : /(?:full.time|دوام كامل)/i.test(text) ? 'full-time'
 : /(?:contract|مؤقت|لمدة يوم)/i.test(text) ? 'contract' : 'unspecified';
const language = /[\u0600-\u06FF]/.test(text) ? 'ar' : 'en';
const missing = [];
if(!title)missing.push('job_title');
if(!city)missing.push('UAE_city');
const confidence = Math.min(1,0.45+(title?0.25:0)+(city?0.20:0)+(pay?0.05:0)+(workDate?0.05:0));
if(missing.length) return [{json:{state:'needs_review',reason:'missing_required_fields',
  missing_fields:missing,external_id:m.external_id,language,confidence}}];
const job={external_id:m.external_id,title,city,language,employment_type:employmentType,
  pay,work_date:workDate,source:'waha-webhook',
  test_retry:m.test_retry===true};
return [{json:{state:'ready',job,confidence}}];

const response = $input.first().json;
return [{json:{
  state:response.duplicate ? 'duplicate' : 'submitted',
  external_id:response.external_id || '',
  stored:response.stored===true,
  duplicate:response.duplicate===true,
  destination:'local-demo-job-form'
}}];

const payload = $input.first().json;
return [{json:{state:'delivery_failed',retryable:true,reason:'destination_api_error',
  error_type:payload.error?.name || payload.error?.message || 'http_failure',
  destination:'local-demo-job-form'}}];
